131|<body>
132|<header class="topbar">
133|<div class="topbar-main">
134|<a class="brand" href="/">Fleet SRE</a>
135|<a class="grid-link" href="/">Fleet grid</a>
136|<div class="topbar-right">
137|<span class="clock" title="Sim time">{{ demo.now[11:19] }}</span>
138|{% if demo.live %}<span class="pill">Live: {{ demo.model }}</span>{% else %}<span class="pill">Scripted replay</span>{% endif %}
139|{% if admin %}<span class="pill pill-admin">Admin</span>{% endif %}
140|{% if demo.held %}<span class="pill pill-held">Clock held</span>{% endif %}
141|</div>
142|</div>
143|<div class="topbar-meta">
144|{% if admin_error %}<span class="meta-notice">admin token not accepted</span>{% endif %}
145|<span>Model calls: {{ demo.model_calls }}{% if demo.last_model_call_at %} (last {{ demo.last_model_call_at[11:19] }}){% endif %}</span>
146|<span>Active faults:{% if demo.active_faults %} {% for f in demo.active_faults %}{{ f.id }} {{ f.type }} {{ f.environment }}{% if not loop.last %}; {% endif %}{% endfor %}{% else %} none{% endif %}</span>
147|{% if demo.exhausted %}<span class="meta-notice">script ended: switch act to restart</span>{% endif %}
148|<span id="stale">updated: reload</span>
149|</div>
150|</header>
151|<div class="demo-strip">
152|<div class="demo-strip-inner">
153|<span class="demo-label">Demo</span>
154|{% if admin %}
155|<span class="demo-fault-label">Demo fault:</span>
156|<div class="segments" role="group" aria-label="Demo fault">
157|{% for name in demo.acts %}
158|<button type="button" class="seg{% if name == demo.act %} seg-current{% endif %}" title="{{ name }}" data-url="/api/demo/act" data-method="POST" data-act="{{ name }}"{% if name == demo.act %} aria-current="true"{% endif %}>{{ demo.act_titles[name] }}</button>
159|{% endfor %}
160|</div>
161|<button type="button" class="seg-restart" title="Restart {{ demo.act }}" data-url="/api/demo/act" data-method="POST" data-act="{{ demo.act }}">Restart this act</button>
162|{% else %}
163|<span class="act-label">Act {{ demo.act }} &mdash; {{ demo.title }}</span>
164|{% endif %}
165|</div>
166|</div>
167|<main>
168|{% block content %}{% endblock %}
169|</main>
170|<script>
171|(function () {
172|  function showError(message) {
173|    var err = document.getElementById("action-error");
174|    if (err) {
175|      err.textContent = message;
176|      err.style.display = "block";
177|    }
178|  }
179|  document.addEventListener("click", function (event) {
180|    var btn = null;
181|    if (event.target && event.target.closest) {
182|      btn = event.target.closest("button[data-url]");
183|    }
184|    if (!btn || btn.disabled) {
185|      return;
186|    }
187|    var url = btn.getAttribute("data-url");
188|    var method = btn.getAttribute("data-method") || "POST";
189|    var body = {};
190|    if (btn.hasAttribute("data-act")) {
191|      body = {act: btn.getAttribute("data-act")};
192|    } else {
193|      var from = btn.getAttribute("data-body-from");
194|      var fields = btn.getAttribute("data-field");
195|      if (from && fields) {
196|        var ids = from.split(",");
197|        var keys = fields.split(",");
198|        for (var i = 0; i < ids.length; i++) {
199|          var inputId = ids[i].trim();
200|          var key = (keys[i] || "").trim();
201|          if (!inputId || !key) {
202|            continue;
203|          }
204|          var input = document.getElementById(inputId);
205|          if (!input) {
206|            continue;
207|          }
208|          if (input.type === "number") {
209|            var n = parseInt(input.value || "0", 10);
210|            body[key] = isNaN(n) ? 0 : n;
211|          } else {
212|            body[key] = input.value;
213|          }
214|        }
215|      }
216|    }
217|    var original = btn.textContent;
218|    btn.disabled = true;
219|    btn.textContent = "Sent\u2026";
220|    function restore() {
221|      btn.disabled = false;
222|      btn.textContent = original;
223|    }
224|    fetch(url, {method: method, headers: {"Content-Type": "application/json"}, body: JSON.stringify(body)}).then(function (resp) {
225|      if (resp.ok) {
226|        if (url === "/api/demo/act") {
227|          window.location.href = "/";
228|        } else {
229|          window.location.reload();
230|        }
231|      } else {
232|        resp.json().then(function (data) {
233|          var msg = (data && data.error) ? data.error : ("request failed: " + resp.status);
234|          restore();
235|          showError(msg);
236|        }).catch(function () {
237|          restore();
238|          showError("request failed: " + resp.status);
239|        });
240|      }
241|    }).catch(function (err) {
242|      restore();
243|      showError(String(err && err.message ? err.message : err));
244|    });
245|  });
246|})();
247|</script>
248|<script>
249|(function () {
250|  var known = null;
251|  function poll() {
252|    fetch("/api/version").then(function (r) { return r.json(); }).then(function (data) {
253|      if (known === null) { known = data.version; return; }
254|      if (data.version !== known) {
255|        if (document.querySelector("details[open]")) {
256|          document.getElementById("stale").style.display = "block";
257|          known = data.version;
258|        } else { window.location.reload(); }
259|      }
260|    }).catch(function () {});
261|  }
262|  setInterval(poll, 2000);
263|})();
264|</script>
265|{% block scripts %}{% endblock %}
266|</body>
267|</html>

