151|<div class="demo-strip">
152|<div class="demo-strip-inner">
153|<span class="demo-label">Demo</span>
154|{% if admin %}
155|<span class="demo-fault-label">Demo fault:</span>
156|<div class="segments" role="group" aria-label="Demo fault">
157|{% for name in demo.acts %}
158|<button type="button" class="seg{% if name == demo.act %} seg-current{% endif %}" title="{{ name }}" data-url="/api/demo/act" data-method="POST" data-act="{{ name }}"{% if name == demo.act %} aria-current="true"{% endif %}>{{ demo.act_titles[name] }}</button>
159|{% endfor %}
160|</div>
161|<button type="button" class="seg-restart" title="Restart {{ demo.act }}" data-url="/api/demo/act" data-method="POST" data-act="{{ demo.act }}">Restart this act</button>
162|{% else %}
