(function () {
  var known = null;
  function poll() {
    if (window.__sreRunning) { return; }
    fetch("/api/version").then(function (r) { return r.json(); }).then(function (data) {
      if (known === null) { known = data.version; return; }
      if (data.version !== known) {
        if (document.querySelector("details[open]")) {
          document.getElementById("stale").style.display = "block";
          known = data.version;
        } else { window.location.reload(); }
      }
    }).catch(function () {});
  }
  setInterval(poll, 2000);
})();
</script>
<script>
(function () {
  var TRIGGER_WORDS = {
    opened: "tripwire tripped",
    reply: "you replied",
    tripwire: "tripwire state changed",
    rejection: "you rejected the proposal",
    conflict: "resource changed since the proposal",
    invalid_patch: "proposal was invalid",
    apply_failed: "apply failed",
    verification_failed: "verification failed"
  };
  var SEGMENT_WORDS = {
    start: "first investigation",
    resume: "resumed investigation",
    reopen: "reopened investigation"
  };
  function triggerWords(trigger) {
    if (TRIGGER_WORDS[trigger]) { return TRIGGER_WORDS[trigger]; }
    return String(trigger || "").replace(/_/g, " ");
  }
  function segmentWords(segment) {
    if (SEGMENT_WORDS[segment]) { return SEGMENT_WORDS[segment]; }
    return String(segment || "").replace(/_/g, " ");
  }
  var prev = null;
  function setButtonsDisabled(running) {
    var buttons = document.querySelectorAll("button[data-url]");
    for (var i = 0; i < buttons.length; i++) {
      var btn = buttons[i];
      if (running) {
        if (!btn.disabled) {
          if (btn.dataset.orig === undefined) {
            btn.dataset.orig = btn.textContent;
          }
          btn.disabled = true;
          btn.textContent = "SRE is working";
        }
      } else if (btn.dataset.orig !== undefined) {
        btn.disabled = false;
        btn.textContent = btn.dataset.orig;
        delete btn.dataset.orig;
      }
    }
  }
  function render(data) {
    var panel = document.getElementById("sre-activity");
    var meta = document.getElementById("sre-meta");
    var elapsed = document.getElementById("sre-elapsed");
    var turnsBox = document.getElementById("sre-turns");
    var waiting = document.getElementById("sre-waiting");
    if (!panel) { return; }
    var parts = [];
    if (data.model) { parts.push(data.model); }
    if (data.deployment) { parts.push(data.deployment); }
    var seg = segmentWords(data.segment);
    var trig = triggerWords(data.trigger);
    if (seg || trig) { parts.push(seg + " \u2014 " + trig); }
    meta.textContent = parts.join(" \u00b7 ");
    var secs = Math.round(data.elapsed_s || 0);
    elapsed.textContent = secs + "s";
    while (turnsBox.firstChild) {
      turnsBox.removeChild(turnsBox.firstChild);
    }
    var turns = data.turns || [];
    for (var i = 0; i < turns.length; i++) {
      var turn = turns[i];
      var row = document.createElement("div");
      row.className = "sre-turn";
      var n = document.createElement("span");
      n.className = "sre-turn-n";
      n.textContent = "Turn " + turn.n;
      row.appendChild(n);
      var tool = document.createElement("span");
      tool.className = "sre-turn-tool";
      tool.textContent = turn.tool || "no tool call";
      row.appendChild(tool);
      if (turn.rationale) {
        var think = document.createElement("span");
        think.className = "sre-turn-think";
        think.textContent = turn.rationale;
        row.appendChild(think);
      }
      var chip = document.createElement("span");
      chip.className = "verdict verdict-" + (turn.verdict || "");
      chip.textContent = turn.verdict || "";
      row.appendChild(chip);
      turnsBox.appendChild(row);
    }
    waiting.hidden = !data.call_in_flight;
    panel.hidden = false;
  }
  function poll() {
    fetch("/api/demo/activity").then(function (r) {
      return r.json();
    }).then(function (data) {
      var running = data && data.state === "running";
      window.__sreRunning = running;
      if (running) {
        render(data);
        setButtonsDisabled(true);
      } else {
        var panel = document.getElementById("sre-activity");
        if (panel) { panel.hidden = true; }
        setButtonsDisabled(false);
      }
      if (prev === "running" && data.state === "idle") {
        window.location.reload();
        return;
      }
      prev = data.state;
    }).catch(function () {});
  }
  setInterval(poll, 1000);
  poll();
})();
</script>"}

